import{Q as e,Tt as t,et as n,j as r,nt as i,xt as a}from"./chunks/framework.D7GyxgT6.js";var o=JSON.parse(`{"title":"What is watermark-js-plus?","description":"Learn how watermark-js-plus adds visible, image, and blind watermarks to browser pages with framework-agnostic TypeScript APIs.","frontmatter":{"layout":"doc","description":"Learn how watermark-js-plus adds visible, image, and blind watermarks to browser pages with framework-agnostic TypeScript APIs."},"headers":[],"relativePath":"guide/what-is-this.md","filePath":"en/guide/what-is-this.md"}`),s={name:`guide/what-is-this.md`};function c(r,o,s,c,l,u){let d=t(`el-backtop`);return a(),e(`div`,null,[i(d),o[0]||=n(`<h1 id="what-is-watermark-js-plus" tabindex="-1">What is watermark-js-plus? <a class="header-anchor" href="#what-is-watermark-js-plus" aria-label="Permalink to “What is watermark-js-plus?”">​</a></h1><p><code>watermark-js-plus</code> is a lightweight, Canvas-based TypeScript library for adding watermarks in the browser. It works with vanilla JavaScript and frontend frameworks without requiring a framework-specific adapter.</p><p>Use it to add visible watermarks to pages and containers, render watermarks directly into existing images, or create and reveal low-opacity blind watermarks.</p><h2 id="three-watermark-capabilities" tabindex="-1">Three Watermark Capabilities <a class="header-anchor" href="#three-watermark-capabilities" aria-label="Permalink to “Three Watermark Capabilities”">​</a></h2><ul><li><strong>Visible watermarks</strong> — Add text, multi-line text, images, or rich text to an entire page or a specific container, with flexible layouts, styling, runtime updates, and optional DOM tamper recovery.</li><li><strong>Image watermarks</strong> — Render text or image watermarks directly into an existing <code>&lt;img&gt;</code> element in the browser.</li><li><strong>Blind watermarks</strong> — Add low-opacity watermarks and visually enhance them from screenshots or images with built-in decoding.</li></ul><h2 id="built-for-frontend-development" tabindex="-1">Built for Frontend Development <a class="header-anchor" href="#built-for-frontend-development" aria-label="Permalink to “Built for Frontend Development”">​</a></h2><ul><li><strong>Framework agnostic</strong> — Use the same browser API with vanilla JavaScript, React, Vue, Angular, Svelte, and other frontend frameworks.</li><li><strong>TypeScript first</strong> — Use complete public type declarations for configuration and lifecycle APIs.</li><li><strong>ES module support</strong> — Import from the standard package entry with modern bundlers, or use the preserved-module <code>watermark-js-plus/es</code> entry when you need explicit ES module imports. See <a href="/watermark-js-plus/guide/extra/on-demand.html">ES Module Imports</a>.</li></ul><h2 id="browser-support" tabindex="-1">Browser Support <a class="header-anchor" href="#browser-support" aria-label="Permalink to “Browser Support”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/chrome/chrome_48x48.png" alt="Chrome"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/firefox/firefox_48x48.png" alt="Firefox"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/safari/safari_48x48.png" alt="Safari"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/opera/opera_48x48.png" alt="Opera"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/edge/edge_48x48.png" alt="Edge"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/master/src/archive/internet-explorer_9-11/internet-explorer_9-11_48x48.png" alt="IE"></th></tr></thead><tbody><tr><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">Latest ✔</td><td style="text-align:center;">11 with <code>/ie</code> ✔</td></tr></tbody></table><p>The default package entry targets modern browsers. For IE11 and partial IE10/IE9 support, use the dedicated legacy-browser entry:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Watermark } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;watermark-js-plus/ie&#39;</span></span></code></pre></div><p>See <a href="/watermark-js-plus/guide/extra/ie.html">Legacy Browser Support</a> for usage and blind-watermark decoding compatibility.</p>`,12)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};